mapper.select:
SELECT p.*, m.nick_name as author, m.profile_image_url as profileImageUrl, c.name as categoryName, (SELECT COUNT(*) FROM TB_LIKE WHERE post_idx = p.idx AND comment_idx IS NULL) as likeCount, (SELECT COUNT(*) FROM TB_UNLIKE WHERE post_idx = p.idx AND comment_idx IS NULL) as unlikeCount, (SELECT COUNT(*) FROM TB_COMMENT WHERE post_idx = p.idx) as commentCount, CASE WHEN EXISTS ( SELECT 1 FROM TB_LIKE WHERE post_idx = p.idx AND member_idx = #{memberIdx} AND comment_idx IS NULL ) THEN true ELSE false END as isLiked, CASE WHEN EXISTS ( SELECT 1 FROM TB_UNLIKE WHERE post_idx = p.idx AND member_idx = #{memberIdx} AND comment_idx IS NULL ) THEN true ELSE false END as isUnliked FROM TB_POST p LEFT JOIN TB_MEMBER m ON p.member_idx = m.idx LEFT JOIN TB_CATEGORY c ON p.category_idx = c.idx
AND p.category_idx = #{categoryIdx}
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR m.nick_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY p.created_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM TB_POST p LEFT JOIN TB_MEMBER m ON p.member_idx = m.idx
AND p.category_idx = #{categoryIdx}
AND ( p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%') OR m.nick_name LIKE CONCAT('%', #{keyword}, '%') )

mapper.update:
UPDATE TB_POST
SET view_count = view_count + 1
WHERE idx = #{postIdx}

mapper.delete:
DELETE FROM TB_POST
WHERE idx = #{postIdx}
